def remove_covered_intervals_brute(intervals):
    n = len(intervals)
    covered = [False] * n
    for i in range(n):
        for j in range(n):                                  # check every OTHER interval
            if i != j and intervals[j][0] <= intervals[i][0] and intervals[i][1] <= intervals[j][1]:
                if intervals[j] != intervals[i]:
                    covered[i] = True
                    break
    return sum(1 for c in covered if not c)

