public class Main {
    static int removeCoveredIntervalsBrute(int[][] intervals) {
        int n = intervals.length;
        boolean[] covered = new boolean[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {                       // check every OTHER interval
                if (i != j && intervals[j][0] <= intervals[i][0] && intervals[i][1] <= intervals[j][1]) {
                    covered[i] = true;
                    break;
                }
            }
        }
        int count = 0;
        for (boolean c : covered) if (!c) count++;
        return count;
    }
}

