import java.util.*;

public class Main {
    static int removeCoveredIntervals(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);   // start asc, end desc
        int count = 0;
        int prevEnd = Integer.MIN_VALUE;
        for (int[] iv : intervals) {
            if (iv[1] > prevEnd) {                              // not covered by anything so far
                count++;
                prevEnd = iv[1];
            }
        }
        return count;
    }
}

