#include <bits/stdc++.h>
using namespace std;

int removeCoveredIntervals(vector<vector<int>>& intervals) {
    sort(intervals.begin(), intervals.end(), [](vector<int>& a, vector<int>& b) {
        return a[0] != b[0] ? a[0] < b[0] : a[1] > b[1];             // start asc, end desc for ties
    });
    int count = 0;
    int prevEnd = INT_MIN;
    for (auto& iv : intervals) {
        if (iv[1] > prevEnd) {                                          // not covered by anything so far
            count++;
            prevEnd = iv[1];
        }
    }
    return count;
}
